<?phpclass Banco{	private static $conexao = null;	private static function Conectar()	{		if (self::$conexao !== null) {			return;		}		try {			self::$conexao = new PDO(				'mysql:host=localhost;dbname=saf;charset=utf8mb4', 'root', 'root',				[					PDO::ATTR_ERRMODE			=> PDO::ERRMODE_EXCEPTION,					PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,					PDO::ATTR_EMULATE_PREPARES   => false,				]			);		} catch (PDOException $Erro) {			throw new Exception('Erro ao conectar ao Servidor.');		}	}	protected static function Consultar($comando)	{		self::Conectar();		$cSQL = self::$conexao->prepare($comando);		$cSQL->execute();		$dados = $cSQL->fetchAll(PDO::FETCH_ASSOC);		$cSQL->closeCursor();		return $dados;	}	protected static function Executar($comando)	{		self::Conectar();		$cSQL = self::$conexao->prepare($comando);		$cSQL->execute();		$cSQL->closeCursor();	}}?>